import * as React from 'react';
import * as styles from './Navigation.module.scss';
export function useStickynav(stickyRef, isPost, activeClass) {
    const [isActive, setIsActive] = React.useState(false);
    React.useEffect(()=>{
        let frame = null;
        const update = ()=>{
            if (frame !== null) cancelAnimationFrame(frame);
            frame = requestAnimationFrame(()=>{
                frame = null;
                const target = stickyRef?.current;
                if (!target) {
                    setIsActive(false);
                    return;
                }
                const trigger = target.getBoundingClientRect().top + window.scrollY;
                const triggerOffset = isPost ? target.offsetHeight + 35 : -20;
                setIsActive(window.scrollY >= trigger + triggerOffset);
            });
        };
        update();
        window.addEventListener('scroll', update, {
            passive: true
        });
        window.addEventListener('resize', update);
        return ()=>{
            if (frame !== null) cancelAnimationFrame(frame);
            window.removeEventListener('scroll', update);
            window.removeEventListener('resize', update);
        };
    }, [
        isPost,
        stickyRef
    ]);
    const currentClass = isActive ? activeClass : '';
    const navBackgroundClass = isActive ? styles.siteNavBackground : '';
    return {
        currentClass,
        navBackgroundClass
    };
}
